-- SonicDemixer local schema reference: SQLite / Room.
-- Timestamps are UTC epoch milliseconds. UUIDs are TEXT generated by the app.
PRAGMA foreign_keys = ON;

CREATE TABLE app_install (
  owner_id TEXT PRIMARY KEY NOT NULL,
  created_at INTEGER NOT NULL,
  app_instance_version TEXT NOT NULL
);

CREATE TABLE projects (
  id TEXT PRIMARY KEY NOT NULL,
  owner_id TEXT NOT NULL,
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 160),
  source_uri TEXT NOT NULL,
  source_path TEXT,
  source_name TEXT NOT NULL,
  source_format TEXT NOT NULL,
  source_size_bytes INTEGER NOT NULL CHECK (source_size_bytes >= 0),
  source_sha256 TEXT,
  duration_ms INTEGER NOT NULL CHECK (duration_ms > 0),
  sample_rate INTEGER NOT NULL CHECK (sample_rate > 0),
  channels INTEGER NOT NULL CHECK (channels BETWEEN 1 AND 8),
  status TEXT NOT NULL DEFAULT 'imported'
    CHECK (status IN ('imported','queued','processing','ready','failed')),
  last_error_code TEXT,
  last_error_message TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (owner_id) REFERENCES app_install(owner_id) ON DELETE CASCADE
);
CREATE INDEX idx_projects_owner_updated ON projects(owner_id, updated_at DESC);
CREATE INDEX idx_projects_owner_status ON projects(owner_id, status);

CREATE TABLE separation_jobs (
  id TEXT PRIMARY KEY NOT NULL,
  owner_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  model_id TEXT NOT NULL,
  model_version TEXT NOT NULL,
  preset TEXT NOT NULL,
  requested_stems_json TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued','running','cancel_requested','cancelled','failed','completed')),
  progress REAL NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress <= 100),
  idempotency_key TEXT NOT NULL,
  attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  started_at INTEGER,
  finished_at INTEGER,
  error_code TEXT,
  error_message TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (owner_id) REFERENCES app_install(owner_id) ON DELETE CASCADE,
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  UNIQUE (owner_id, idempotency_key)
);
CREATE INDEX idx_jobs_owner_project ON separation_jobs(owner_id, project_id, created_at DESC);
CREATE INDEX idx_jobs_project_status ON separation_jobs(project_id, status);
CREATE INDEX idx_jobs_owner_status ON separation_jobs(owner_id, status);
CREATE UNIQUE INDEX uq_one_active_job_per_project
  ON separation_jobs(project_id)
  WHERE status IN ('queued','running','cancel_requested');

CREATE TABLE stems (
  id TEXT PRIMARY KEY NOT NULL,
  owner_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  job_id TEXT NOT NULL,
  kind TEXT NOT NULL
    CHECK (kind IN ('vocals','drums','bass','other','guitar','piano','keyboard','strings','custom')),
  display_name TEXT NOT NULL,
  file_path TEXT NOT NULL,
  file_sha256 TEXT,
  codec TEXT NOT NULL,
  sample_rate INTEGER NOT NULL CHECK (sample_rate > 0),
  channels INTEGER NOT NULL CHECK (channels BETWEEN 1 AND 8),
  frame_count INTEGER NOT NULL CHECK (frame_count > 0),
  duration_ms INTEGER NOT NULL CHECK (duration_ms > 0),
  gain_db REAL NOT NULL DEFAULT 0 CHECK (gain_db BETWEEN -60 AND 12),
  muted INTEGER NOT NULL DEFAULT 0 CHECK (muted IN (0,1)),
  solo INTEGER NOT NULL DEFAULT 0 CHECK (solo IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (owner_id) REFERENCES app_install(owner_id) ON DELETE CASCADE,
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  FOREIGN KEY (job_id) REFERENCES separation_jobs(id) ON DELETE CASCADE,
  UNIQUE (job_id, kind)
);
CREATE INDEX idx_stems_owner_project ON stems(owner_id, project_id, sort_order);
CREATE INDEX idx_stems_job ON stems(job_id);

CREATE TABLE exports (
  id TEXT PRIMARY KEY NOT NULL,
  owner_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  job_id TEXT,
  scope TEXT NOT NULL CHECK (scope IN ('stem','all_stems','mix')),
  stem_id TEXT,
  format TEXT NOT NULL CHECK (format IN ('wav','mp3')),
  destination_uri TEXT,
  destination_path TEXT,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued','running','completed','partial','failed','cancelled')),
  idempotency_key TEXT NOT NULL,
  error_code TEXT,
  error_message TEXT,
  created_at INTEGER NOT NULL,
  finished_at INTEGER,
  FOREIGN KEY (owner_id) REFERENCES app_install(owner_id) ON DELETE CASCADE,
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  FOREIGN KEY (job_id) REFERENCES separation_jobs(id) ON DELETE SET NULL,
  FOREIGN KEY (stem_id) REFERENCES stems(id) ON DELETE SET NULL,
  UNIQUE (owner_id, idempotency_key),
  CHECK ((scope = 'stem' AND stem_id IS NOT NULL) OR (scope IN ('all_stems','mix') AND stem_id IS NULL))
);
CREATE INDEX idx_exports_owner_project ON exports(owner_id, project_id, created_at DESC);
CREATE INDEX idx_exports_project_status ON exports(project_id, status);

CREATE TABLE app_settings (
  owner_id TEXT PRIMARY KEY NOT NULL,
  language TEXT NOT NULL DEFAULT 'ar',
  theme TEXT NOT NULL DEFAULT 'system' CHECK (theme IN ('light','dark','system')),
  default_format TEXT NOT NULL DEFAULT 'wav' CHECK (default_format IN ('wav','mp3')),
  keep_source INTEGER NOT NULL DEFAULT 1 CHECK (keep_source IN (0,1)),
  auto_cleanup_cache INTEGER NOT NULL DEFAULT 1 CHECK (auto_cleanup_cache IN (0,1)),
  processing_mode TEXT NOT NULL DEFAULT 'offline' CHECK (processing_mode IN ('offline')),
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (owner_id) REFERENCES app_install(owner_id) ON DELETE CASCADE
);

CREATE TABLE model_assets (
  id TEXT PRIMARY KEY NOT NULL,
  owner_id TEXT NOT NULL,
  version TEXT NOT NULL,
  runtime TEXT NOT NULL,
  asset_path TEXT NOT NULL,
  sha256 TEXT NOT NULL,
  licence_id TEXT NOT NULL,
  source_url TEXT NOT NULL,
  redistribution_allowed INTEGER NOT NULL CHECK (redistribution_allowed IN (0,1)),
  verified INTEGER NOT NULL DEFAULT 0 CHECK (verified IN (0,1)),
  minimum_ram_bytes INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (owner_id) REFERENCES app_install(owner_id) ON DELETE CASCADE,
  UNIQUE (owner_id, id, version)
);
CREATE INDEX idx_model_assets_owner_verified ON model_assets(owner_id, verified);
